    private class Run(val code: Int, val out: List<String>, val err: List<String>)

    private val args = arrayOf("--server", "http://127.0.0.1:8080", "--user", "Alice")

    private fun line(text: String): Step = Step.Line(text)

    private fun act(action: () -> Unit): Step = Step.Act(action)

    private suspend fun TestScope.drive(fake: FakeServerTransport, steps: List<Step>, arguments: Array<String> = args): Run {
        val queue = ArrayDeque(steps)
        val out = mutableListOf<String>()
        val err = mutableListOf<String>()
        val app = DriverApp(
            transportFactory = { fake },
            readLine = {
                var next = queue.removeFirstOrNull()
                while (next is Step.Act) {
                    next.action()
                    next = queue.removeFirstOrNull()
                }
                (next as? Step.Line)?.text
            },
            writeLine = { out += it },
            writeError = { err += it },
            context = backgroundScope.coroutineContext,
            scheduler = FakeScheduler(),
        )
        val code = app.run(arguments)
        return Run(code, out, err)
    }

    private fun TestScope.fakeTransport(server: FakeServer = FakeServer()) = FakeServerTransport(server) { testScheduler.currentTime }

    private fun snapshot(line: String): ClientSnapshot = WireJson.json.decodeFromString(ClientSnapshot.serializer(), line)

